package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** $doc */
public class ${kind}Plan {
    public void ${call}(@PathVariable("sheetId") String sheetId, @RequestBody PlanPauseRequest request, @Val Plan plan,
            PlanRepository plans, PersonRepository people, Audit audit) throws InvalidPlanException {
        String sheet = sheetId.trim();
        String by = request == null || request.by() == null ? "" : request.by().trim();
        if (${cond}) {
            throw new InvalidPlanException("${msg}");
        }
        Person person = people.find(sheet, plan.personId());
        plans.${call}(sheet, plan.id());
        audit.record("${ev} sheet=" + sheet + " by=" + by + " name=" + (person == null ? "" : person.name())
